import java.util.*;class Solution{record Request(String method,String path,String version){}static Request parse(String line){if(line.length()>4096)throw new IllegalArgumentException("too long");String[]parts=line.split(" ",-1);if(parts.length!=3||!Set.of("GET","POST","PUT","DELETE").contains(parts[0])||!parts[1].startsWith("/")||!parts[2].startsWith("HTTP/"))throw new IllegalArgumentException("request line");return new Request(parts[0],parts[1],parts[2]);}}
